import{_ as n,C as a,c as d,o as r,j as t,G as i,ak as l,a as p}from"./chunks/framework.D7ejh1zC.js";const f=JSON.parse('{"title":"根据 ChangeId 合并部分提交","description":"","frontmatter":{},"headers":[],"relativePath":"module/git/根据 ChangeId 合并部分提交.md","filePath":"concept/module/git/根据 ChangeId 合并部分提交.md","lastUpdated":1786880804000}'),h={name:"module/git/根据 ChangeId 合并部分提交.md"};function g(_,e,m,k,u,b){const o=a("mdInfo"),s=a("NolebaseGitContributors"),c=a("NolebaseGitChangelog");return r(),d("div",null,[e[0]||(e[0]=t("h1",{id:"根据-changeid-合并部分提交",tabindex:"-1"},[p("根据 ChangeId 合并部分提交 "),t("a",{class:"header-anchor",href:"#根据-changeid-合并部分提交","aria-label":'Permalink to "根据 ChangeId 合并部分提交"'},"​")],-1)),i(o),e[1]||(e[1]=l('<h2 id="git-cherry-pick背景" tabindex="-1">Git cherry-pick背景 <a class="header-anchor" href="#git-cherry-pick背景" aria-label="Permalink to &quot;Git cherry-pick背景&quot;">​</a></h2><p>在项目最开始，客户没有要求每个图层独立部署，因此大家都是设置各自的分支，自己负责的图层在各自分支上提交。项目临近末尾时，客户要求每个图层独立部署，因此需要每个图层设置自己的独立分支。</p><p>由于项目前期并未做此限制，因此在合并时，有个同事出现了 “只想要合并某个提交，但是会把全部提交都合并过去” 的情况。</p><p>为此，询问了 ChatGPT 如何处理这种情况，得到了如下答案。</p><h2 id="git-cherry-pick步骤" tabindex="-1">Git cherry-pick步骤 <a class="header-anchor" href="#git-cherry-pick步骤" aria-label="Permalink to &quot;Git cherry-pick步骤&quot;">​</a></h2><ol><li><p>切换回自己的代码分支，通过 <code>git log</code> 命令来查看提交的 ChangeId。 <img src="https://pic.imgdb.cn/item/66dff0c9d9c307b7e9bc67a8.png" alt="git log 效果" loading="lazy"></p></li><li><p>切换到要合并的代码分支，使用<code>git cherry-pick</code>命令来合并部分提交。例如，如果需要合并 ChangeId 为<code>85e61939874376c3397789f3d5894e169c5d1711</code>的提交，可以使用以下命令：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cherry-pick</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 85e61939874376c3397789f3d5894e169c5d1711</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>若出现冲突，则解决冲突后，执行如下操作：</p><ul><li><code>git add .</code></li><li><code>git commit -m</code></li><li><code>git push</code></li></ul></li></ol>',6)),i(s),i(c)])}const y=n(h,[["render",g]]);export{f as __pageData,y as default};
